-- =====================================================================
-- ERP Albion - Importacion real de ingenieria.maquinas
--
-- 1618 filas de la tabla legacy `maquinas`, mismo criterio que
-- 008_import_articulos.sql (parseado directo del dump, no ETL vivo).
-- Preserva el id original porque despiece*/ordenes_trabajo lo van a
-- referenciar por numero cuando se migren.
--
-- Decisiones tomadas con el usuario:
-- - tipo_maquina_id: se resuelve contra ingenieria.tipos_maquina, que
--   012_tipos_maquina.sql ya dejo con las 34 categorias reales del
--   legacy + el id 80 "Servicio y Reparacion" (maquinas con plano
--   "SR_*", 286 filas -- 17.7% del total -- que el legacy nunca dio de
--   alta como tipo formal, confirmado con el usuario).
-- - precio_lista/moneda/valor_materiales/fecha_valor_materiales: NO se
--   migran, columnas eliminadas (014_maquinas_sin_precio.sql) -- uso
--   real minimo (0.1%-0.6%) y el usuario pidio sacarlo.
-- - nomenclador: NO se migra (015_maquinas_sin_nomenclador.sql) --
--   mismo criterio, 0.7% de uso, el usuario lo descarto.
-- - impuesto/pais_id/ciudad_id/TipodeProyecto: 0% de uso real en las
--   1618 filas, no se migran (no se agrego columna para esto).
-- - imagen_url/dxf_url: SI importan (a diferencia de lo anterior, el
--   usuario los marco como referencias a archivos de planos muy
--   importantes) pero quedan en NULL en este paso -- no hay carpeta de
--   archivos todavia (ver charla equivalente con articulos: se migra
--   primero la fila, las imagenes/dxf se vinculan aparte cuando el
--   usuario entregue la carpeta). 933/1618 (57.7%) tienen imagen legacy,
--   425/1618 (26.3%) tienen dxf legacy -- los nombres de archivo dxf
--   tienen ":" (invalido en Windows), va a necesitar sanitizarse al
--   copiar.
--
-- La fila demo (id=1, plano_id='50641-M1', creada a mano durante
-- pruebas) se borra primero: el legacy real tambien tiene id=1 con el
-- mismo plano_id ('50641-M1', maquina real, no coincidencia), asi que
-- la fila real la reemplaza sin remapeo. Sin referencias que la
-- bloqueen (confirmado: 0 en ordenes_trabajo, maquinas_rubros vacia).
-- =====================================================================

DELETE FROM ingenieria.maquinas WHERE id = 1;

ON CONFLICT (id) DO NOTHING;

SELECT setval(pg_get_serial_sequence('ingenieria.maquinas', 'id'), (SELECT MAX(id) FROM ingenieria.maquinas));
